<script>
(()=>{'use strict';
 const API='./api/kredit/',DATE_API='./api/date/',KODE_API='./api/kode/',HEADS=<?=json_encode($heads,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,ICON_DOWNLOAD=<?=json_encode(mb_svg('download'),JSON_UNESCAPED_SLASHES)?>;
 const KORWIL=[['SEMARANG','Korwil Semarang'],['SOLO','Korwil Solo'],['BANYUMAS','Korwil Banyumas'],['PEKALONGAN','Korwil Pekalongan']];
 const state={view:'kelolaan',rows:[],total:{},kantor:[],userKode:'000',sort:{column:'kode_kantor',direction:'asc'},detail:[],detailKind:'kelolaan',detailAo:'',detailOffice:'',detailBucket:'ALL',detailPage:1,detailSize:20,abort:null};
 const el=id=>document.getElementById(id),ui=()=>window.MonbisUI||{},num=v=>Number(v||0),esc=v=>ui().escape?ui().escape(v):String(v??''),fmt=v=>ui().fmt?ui().fmt(v):new Intl.NumberFormat('id-ID').format(num(v)),fmt2=v=>ui().fmt2?ui().fmt2(v):num(v).toFixed(2);
 const date=v=>{if(!v)return '-';const raw=String(v),d=new Date(raw.length===10?raw+'T00:00:00':raw);return Number.isNaN(d.getTime())?raw:d.toLocaleDateString('id-ID')};
 async function post(url,body,signal){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal}),j=await r.json();if(!r.ok||Number(j.status)!==200)throw new Error(j.message||'Gagal memuat data');return j}
 function user(){if(window.getUser?.())return window.getUser();for(const key of ['dpk_user','app_user','user'])try{const value=JSON.parse(localStorage.getItem(key)||'null');if(value)return value}catch(e){}return {}}
 function userCode(){const raw=user().kode_kantor||user().kode||user().kode_cabang||'000',code=String(raw).replace(/\D/g,'').padStart(3,'0').slice(-3);return code==='099'?'000':code}
 function scope(){const v=el('reportAoArea').value||'ALL';return v.startsWith('KOR-')?{korwil:v.slice(4)}:v.startsWith('CAB-')?{kode_kantor:v.slice(4)}:{}}
 function code(r){return String(r.kode_kantor||r.kode_cabang||'').padStart(3,'0')}
 function name(r){return r.nama_kantor||'-'}
 function aoCode(r){return r.kode_ao||r.kode_group2||''}
 function aoName(r){return r.nama_ao||aoCode(r)||'-'}
 function aoCleanName(r){return aoName(r).replace(/\s*\(SEGERA CLEANSING\)\s*$/i,'').trim()}
 function aoShortName(r){const value=aoCleanName(r);return value.length>15?value.slice(0,15).trimEnd()+'…':value}
 function aoNeedsCleansing(r){return (r.status_ao!==undefined&&r.status_ao!==null&&!num(r.status_ao))||/SEGERA CLEANSING/i.test(aoName(r))}
 function signed(v,p=false){const n=num(v);return '<span class="'+(n<0?'mb-negative':'mb-positive')+'">'+(n>0?'+':n<0?'−':'')+(p?fmt2(Math.abs(n))+'%':fmt(Math.abs(n)))+'</span>'}
 function metric(r,field,noa,bucket,tone){const value=num(r[field]),sub=noa?'<span class="mb-subvalue">'+fmt(r[noa]||0)+' NOA</span>':'',content='<span class="mb-potensi-metric__value">'+fmt(value)+'</span>'+sub;if(aoCode(r)==='ALL')return '<span class="mb-potensi-metric mb-potensi-metric--'+tone+'">'+content+'</span>';return '<button type="button" class="mb-potensi-metric mb-potensi-metric--'+tone+'" data-detail-ao="'+esc(aoCode(r))+'" data-detail-office="'+esc(code(r))+'" data-detail-bucket="'+bucket+'">'+content+'</button>'}
 function realisasiMetric(r){const content='<span class="mb-potensi-metric__value">'+fmt(r.realisasi)+'</span><span class="mb-subvalue">'+fmt(r.noa_realisasi||0)+' NOA</span>';if(aoCode(r)==='ALL')return '<span class="mb-potensi-metric mb-potensi-metric--green">'+content+'</span>';return '<button type="button" class="mb-potensi-metric mb-potensi-metric--green" data-realisasi-ao="'+esc(aoCode(r))+'" data-realisasi-office="'+esc(code(r))+'">'+content+'</button>'}
 function identity(r,total){const c=total?'ALL':code(r),ao=total?(r.nama_ao||fmt(r.total_ao||0)+' AO'):aoCleanName(r),shown=state.view==='kelolaan'?aoShortName(r):ao,content=total?'GRAND TOTAL<span class="mb-subvalue">'+esc(ao)+'</span>':'<button class="mb-link" title="'+esc(ao)+'" data-detail-ao="'+esc(aoCode(r))+'" data-detail-office="'+esc(code(r))+'" data-detail-bucket="ALL">'+esc(shown)+'</button>'+(aoNeedsCleansing(r)?'<span class="mb-subvalue mb-negative">BELUM CLEANSING</span>':'');return '<td class="mb-code-col mb-sticky-left mb-code">'+c+'</td><td class="mb-sticky-left-2 mb-name" style="--mb-sticky-1:44px">'+content+'<span class="mb-potensi-mobile-code">'+c+'</span></td>'}
 function row(r,total=false){let cells;if(state.view==='realisasi')cells='<td class="mb-noa">'+fmt(r.total_noa||0)+'</td><td class="mb-num mb-blue">'+fmt(r.total_realisasi||0)+'</td>';else cells='<td class="mb-num">'+fmt(r.porto_closing)+'</td><td class="mb-num">'+realisasiMetric(r)+'</td><td class="mb-num">'+metric(r,'nominal_0_7','noa_0_7','0_7','green')+'</td><td class="mb-num">'+metric(r,'nominal_8_30','noa_8_30','8_30','amber')+'</td><td class="mb-num">'+metric(r,'nominal_dp','noa_dp','DP','amber')+'</td><td class="mb-num">'+metric(r,'nominal_npl','noa_npl','NPL','red')+'</td><td class="mb-num mb-blue">'+fmt(r.porto_actual)+'</td><td class="mb-num mb-negative">'+fmt2(r.persen_npl)+'%</td><td class="mb-num mb-violet">'+fmt(r.ckpn_closing)+'</td><td class="mb-num mb-violet">'+fmt(r.ckpn_actual)+'</td><td class="mb-num">'+signed(r.selisih_ckpn)+'</td><td class="mb-num">'+signed(r.growth)+'</td><td class="mb-num">'+signed(r.growth_persen,true)+'</td>';return '<tr'+(total?' class="mb-total-row"':'')+'>'+identity(r,total)+cells+'</tr>'}
 function filtered(){const q=String(el('reportAoSearch').value||'').toLowerCase(),dir=state.sort.direction==='asc'?1:-1;return state.rows.filter(r=>!q||[code(r),name(r),aoCode(r),aoName(r)].join(' ').toLowerCase().includes(q)).sort((a,b)=>{const av=state.sort.column==='kode_kantor'?code(a):state.sort.column==='nama_kantor'?name(a):state.sort.column==='nama_ao'?aoName(a):a[state.sort.column],bv=state.sort.column==='kode_kantor'?code(b):state.sort.column==='nama_kantor'?name(b):state.sort.column==='nama_ao'?aoName(b):b[state.sort.column];return Number.isFinite(Number(av))&&av!==''?(num(av)-num(bv))*dir:String(av||'').localeCompare(String(bv||''),'id-ID',{numeric:true})*dir})}
 function render(){el('reportAoTable').querySelector('thead').innerHTML=HEADS[state.view];el('reportAoTotal').innerHTML=Object.keys(state.total||{}).length?row(state.total,true):'';const rows=filtered(),cols=state.view==='realisasi'?4:15;el('reportAoBody').innerHTML=rows.length?rows.map(r=>row(r)).join(''):'<tr><td colspan="'+cols+'" class="mb-empty">Data AO tidak ditemukan.</td></tr>';document.querySelectorAll('[data-ao-view]').forEach(b=>b.classList.toggle('is-active',b.dataset.aoView===state.view));el('reportAoTableTitle').textContent=state.view==='realisasi'?'Realisasi AO':'Kelolaan AO BE';const button=el('reportAoViewSwitch');if(button){button.innerHTML=state.view==='realisasi'?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 20V10M12 20V4M19 20v-7"/><path d="M3 20h18"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/><path d="M8 13h8M8 17h6"/></svg>';button.title=state.view==='realisasi'?'Ganti ke Kelolaan AO BE':'Ganti ke Realisasi AO';button.setAttribute('aria-label',button.title)}}
 async function load(){if(state.abort)state.abort.abort();state.abort=new AbortController();ui().showLoading?.('reportAoLoading',true);try{const payload={type:state.view==='realisasi'?'top realisasi':'kelolaan ao be',closing_date:el('reportAoClosing').value,harian_date:el('reportAoActual').value,...scope()};if(state.view==='realisasi'){payload.page=1;payload.limit=10000}const j=await post(API,payload,state.abort.signal),w=j.data||{};state.rows=w.data||[];state.total=state.view==='realisasi'?{kode_kantor:'ALL',nama_kantor:'GRAND TOTAL',nama_ao:fmt(w.summary?.total_ao||0)+' AO',...w.summary}:w.grand_total||{};state.sort={column:state.view==='realisasi'?'total_realisasi':'kode_kantor',direction:state.view==='realisasi'?'desc':'asc'};render();ui().closeMobileFilter?.('reportAoHeaderFilters')}catch(e){if(e.name!=='AbortError'){console.error(e);state.rows=[];state.total={};render()}}finally{ui().showLoading?.('reportAoLoading',false)}}
 async function datesAndOffices(){const [d,k]=await Promise.all([fetch(DATE_API).then(r=>r.json()),post(KODE_API,{type:'kode_kantor'}).catch(()=>({data:[]}))]);el('reportAoClosing').value=d.data?.last_closing||'';el('reportAoActual').value=d.data?.last_created||'';state.kantor=k.data||[];const s=el('reportAoArea');if(state.userKode!=='000'){const x=state.kantor.find(r=>String(r.kode_kantor).padStart(3,'0')===state.userKode);s.innerHTML='<option value="CAB-'+state.userKode+'">'+state.userKode+' - '+esc(x?.nama_kantor||'Cabang')+'</option>';s.disabled=true}else{s.innerHTML='<option value="ALL">Konsolidasi</option>'+KORWIL.map(x=>'<option value="KOR-'+x[0]+'">'+x[1]+'</option>').join('')+state.kantor.filter(r=>String(r.kode_kantor).padStart(3,'0')!=='000').map(r=>{const c=String(r.kode_kantor).padStart(3,'0');return '<option value="CAB-'+c+'">'+c+' - '+esc(r.nama_kantor)+'</option>'}).join('')}}
 function detailFiltered(){const q=String(el('reportAoDetailSearch').value||'').toLowerCase(),pay=el('reportAoPayment').value,sc=el('reportAoClosingBucket').value;return state.detail.filter(r=>{const dpd=num(r.hari_menunggak_closing),matchSc=sc==='ALL'||(sc==='0_7'?dpd>=0&&dpd<=7:dpd>=8&&dpd<=30),matchPay=pay==='ALL'||(pay==='SUDAH'&&r.status_bayar==='SUDAH BAYAR')||(pay==='LEWAT'&&r.status_bayar==='LEWAT TANGGAL BAYAR / BELUM BAYAR')||(pay==='BELUM_JATUH'&&r.status_bayar==='BELUM JATUH TANGGAL BAYAR');return matchSc&&matchPay&&(!q||[r.no_rekening,r.nama_nasabah,r.alamat,r.kolektibilitas,r.status_rekening,r.pergerakan_bucket,r.va_mandiri,r.va_permata].join(' ').toLowerCase().includes(q))})}
 function detailSummary(rows){const box=el('reportAoDetailSummary'),baki=rows.reduce((s,r)=>s+num(r.baki_debet||r.plafond),0);box.classList.remove('is-hidden');if(state.view==='realisasi'){box.innerHTML='<div class="mb-summary-card mb-summary-card--blue"><div class="mb-summary-card__label">Debitur Realisasi</div><div class="mb-summary-card__value">'+fmt(rows.length)+' NOA</div></div><div class="mb-summary-card mb-summary-card--green"><div class="mb-summary-card__label">Total Realisasi</div><div class="mb-summary-card__value">Rp '+fmt(baki)+'</div></div><div class="mb-summary-card"><div class="mb-summary-card__label">Closing</div><div class="mb-summary-card__value">'+date(el('reportAoClosing').value)+'</div></div><div class="mb-summary-card mb-summary-card--amber"><div class="mb-summary-card__label">Actual</div><div class="mb-summary-card__value">'+date(el('reportAoActual').value)+'</div></div>';return}const sudah=rows.filter(r=>r.status_bayar==='SUDAH BAYAR').length;box.innerHTML='<div class="mb-summary-card mb-summary-card--blue"><div class="mb-summary-card__label">Debitur</div><div class="mb-summary-card__value">'+fmt(rows.length)+' NOA</div></div><div class="mb-summary-card mb-summary-card--green"><div class="mb-summary-card__label">Sudah Bayar</div><div class="mb-summary-card__value">'+fmt(sudah)+' NOA</div></div><div class="mb-summary-card mb-summary-card--red"><div class="mb-summary-card__label">Belum Bayar</div><div class="mb-summary-card__value">'+fmt(rows.length-sudah)+' NOA</div></div><div class="mb-summary-card mb-summary-card--amber"><div class="mb-summary-card__label">Total Baki Debet</div><div class="mb-summary-card__value">Rp '+fmt(baki)+'</div></div>'}
 function renderDetail(){const all=detailFiltered(),pages=Math.max(1,Math.ceil(all.length/state.detailSize));state.detailPage=Math.min(state.detailPage,pages);const start=(state.detailPage-1)*state.detailSize,rows=all.slice(start,start+state.detailSize);detailSummary(all);const realization=state.view==='realisasi';el('reportAoDetailBody').innerHTML='<table class="mb-table mb-detail-mini"><thead><tr><th>Rekening</th><th class="mb-text-left">Nasabah / Alamat</th>'+(realization?'<th>Tgl Realisasi</th><th>Nominal</th>':'<th>Kolek / DPD</th><th>Baki Debet</th><th>Tunggakan P / B</th><th>Status Bayar</th><th>Bayar</th><th>Tgl Bayar</th>')+'</tr></thead><tbody>'+(!rows.length?'<tr><td colspan="8" class="mb-empty">Detail tidak ditemukan.</td></tr>':rows.map(r=>'<tr><td class="mb-code">'+esc(r.no_rekening||'-')+'</td><td class="mb-name">'+esc(r.nama_nasabah||'-')+'<span class="mb-subvalue">'+esc(r.alamat||'-')+'</span></td>'+(realization?'<td class="mb-text-center">'+date(r.tanggal_realisasi)+'</td><td class="mb-num mb-blue">'+fmt(r.plafond)+'</td>':'<td class="mb-text-center">'+esc(r.kolektibilitas||'-')+' / '+fmt(r.hari_menunggak)+'</td><td class="mb-num">'+fmt(r.baki_debet)+'</td><td class="mb-num mb-negative">'+fmt(r.tunggakan_pokok)+' / '+fmt(r.tunggakan_bunga)+'</td><td class="mb-text-center"><span class="mb-pill '+(r.status_bayar==='SUDAH BAYAR'?'mb-pill--success':'mb-pill--danger')+'">'+esc(r.status_bayar)+'</span></td><td class="mb-num mb-positive">'+fmt(r.total_bayar)+'</td><td class="mb-text-center">'+date(r.tgl_bayar_terakhir)+'</td>')+'</tr>').join(''))+'</tbody></table>';el('reportAoDetailMobile').innerHTML=rows.map(r=>'<article class="mb-detail-card"><div class="mb-detail-card__head"><div class="mb-detail-card__identity"><div class="mb-detail-card__name">'+esc(r.nama_nasabah||'-')+'</div><div class="mb-detail-card__meta">'+esc(r.no_rekening||'-')+'</div></div>'+(realization?'':'<span class="mb-pill '+(r.status_bayar==='SUDAH BAYAR'?'mb-pill--success':'mb-pill--danger')+'">'+esc(r.status_bayar)+'</span>')+'</div><div class="mb-detail-card__address"><span>Alamat</span><strong>'+esc(r.alamat||'-')+'</strong></div><div class="mb-detail-card__metrics"><div class="mb-detail-card__metric"><span>'+(realization?'Nominal Realisasi':'Baki Debet')+'</span><strong>Rp '+fmt(realization?r.plafond:r.baki_debet)+'</strong></div><div class="mb-detail-card__metric"><span>'+(realization?'Tanggal Realisasi':'Total Bayar')+'</span><strong>'+(realization?date(r.tanggal_realisasi):'Rp '+fmt(r.total_bayar))+'</strong></div></div></article>').join('');const footer=el('reportAoDetailFooter');footer.classList.toggle('is-hidden',!all.length);footer.innerHTML=!all.length?'':'<div class="mb-detail-page-info">Data '+fmt(start+1)+' - '+fmt(Math.min(start+state.detailSize,all.length))+' dari '+fmt(all.length)+'</div><div class="mb-detail-page-actions"><button class="mb-detail-footer-icon mb-detail-footer-icon--export" id="reportAoDetailExport">'+ICON_DOWNLOAD+'</button><span class="mb-detail-pagination"><button class="mb-detail-page-btn" data-page="prev" '+(state.detailPage<=1?'disabled':'')+'>&lsaquo; Prev</button><span>Hal '+state.detailPage+' / '+pages+'</span><button class="mb-detail-page-btn" data-page="next" '+(state.detailPage>=pages?'disabled':'')+'>Next &rsaquo;</button></span></div>'}
