 }
 function switchView(v){if(v===state.view)return;state.view=v;load()}
 function bind(){document.querySelectorAll('[data-ao-view]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.aoView)));el('reportAoViewSwitch')?.addEventListener('click',()=>switchView(state.view==='realisasi'?'kelolaan':'realisasi'));['reportAoClosing','reportAoActual','reportAoArea'].forEach(id=>el(id).addEventListener('change',load));el('reportAoSearch').addEventListener('input',ui().debounce?ui().debounce(render,150):render);el('reportAoExport').addEventListener('click',()=>exportRows());el('reportAoTable').addEventListener('click',e=>{const d=e.target.closest('[data-detail-ao]');if(d)openDetail(d.dataset.detailAo,d.dataset.detailOffice,d.dataset.detailBucket);const h=e.target.closest('[data-sort]');if(h){const c=h.dataset.sort;state.sort={column:c,direction:state.sort.column===c&&state.sort.direction==='asc'?'desc':'asc'};render()}});['reportAoDetailSearch','reportAoPayment'].forEach(id=>el(id).addEventListener(id.includes('Search')?'input':'change',()=>{state.detailPage=1;renderDetail()}));el('reportAoDetailFooter').addEventListener('click',e=>{if(e.target.closest('#reportAoDetailExport'))exportRows(detailFiltered(),true);const p=e.target.closest('[data-page]')?.dataset.page;if(p){state.detailPage+=p==='next'?1:-1;renderDetail()}})}
 async function init(){state.userKode=userCode();await datesAndOffices();bind();el('reportAoClosingBucket').addEventListener('change',()=>{state.detailPage=1;renderDetail()});el('reportAoPortfolio').addEventListener('change',load);el('reportAoTable').addEventListener('click',e=>{const target=e.target.closest('[data-realisasi-ao]');if(target)openRealisasiFromKelolaan(target.dataset.realisasiAo,target.dataset.realisasiOffice)});load()}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
</script>
